  // String({}) даёт [object Object] — это бесполезно в журнале.
}

01-javascript/15-type-conversion.solution:
function describeValue(value) {
  if (Array.isArray(value)) {
    return value.join(',');
  }

  if (typeof value === 'object' && value !== null) {
    return '[object]';
  }

  return String(value);
}

