  // Цепочка заканчивается значением null.
}

01-javascript/40-prototype-chain.solution:
function protoDepth(value) {
  let depth = 0;
  let current = Object.getPrototypeOf(value);

  while (current !== null) {
    depth += 1;
    current = Object.getPrototypeOf(current);
  }

  return depth;
}

