01-javascript/41-classes.solution:
class TestRun {
  constructor(name) {
    this.name = name;
    this.passed = 0;
    this.failed = 0;
  }

  add(status) {
    if (status === 'passed') {
      this.passed += 1;
    }

    if (status === 'failed') {
      this.failed += 1;
    }
  }

  summary() {
    return `${this.name}: ${this.passed} passed, ${this.failed} failed`;
  }
}

