async function waitFor(read, timeoutMs) {
  const deadline = Date.now() + timeoutMs;

  while (true) {
    const value = read();

    if (value) {
      return value;
    }

    if (Date.now() >= deadline) {
      throw new Error('условие не выполнено');
    }

    await new Promise((resolve) => setTimeout(resolve, 10));
  }
}

