function createWorkItemBuilder() {
  let title = null;
  let priority = 'MEDIUM';
  let built = 0;

  const builder = {
    withTitle(value) {
      title = value;
      return builder;
    },
    withPriority(value) {
      priority = value;
      return builder;
    },
    build() {
      built += 1;

      return {
        title: title ?? 'Задача ' + built,
        description: 'Создано строителем',
        priority
      };
    }
  };

  return builder;
}

