03-automation-qa/223-custom-assertions-a.solution:
function createSoftAssert() {
  const failed = [];

  return {
    check(name, condition) {
      if (!condition) {
        failed.push(name);
      }
    },
    verify() {
      if (failed.length === 0) {
        return;
      }

      throw new Error(
        'Не пройдено проверок: ' + failed.length + ': ' + failed.join(', ')
      );
    }
  };
}
